CREATE TABLE "file_artifacts" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"owner_id" uuid NOT NULL REFERENCES "arena_owners"("id") ON DELETE CASCADE,"uploaded_by_device_id" uuid NOT NULL REFERENCES "arena_devices"("id"),"project_id" uuid,"session_id" uuid REFERENCES "cognitive_sessions"("id") ON DELETE SET NULL,"display_name" text NOT NULL,"media_type" text NOT NULL,"declared_media_type" text NOT NULL,"byte_size" integer NOT NULL,"content_hash" text NOT NULL,"privacy_classification" text NOT NULL,"storage_key" text UNIQUE NOT NULL,"content_base64" text NOT NULL,"status" text DEFAULT 'available' NOT NULL,"created_at" timestamp DEFAULT now() NOT NULL);
CREATE TABLE "node_protocol_requests" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"owner_id" uuid NOT NULL REFERENCES "arena_owners"("id") ON DELETE CASCADE,"control_device_id" uuid NOT NULL REFERENCES "arena_devices"("id"),"node_device_id" uuid NOT NULL REFERENCES "arena_devices"("id"),"capability" text NOT NULL,"resource_id" text NOT NULL,"nonce" text UNIQUE NOT NULL,"issued_at" timestamp NOT NULL,"expires_at" timestamp NOT NULL,"payload_digest" text NOT NULL,"signature" text NOT NULL,"status" text DEFAULT 'issued' NOT NULL,"consumed_at" timestamp,"created_at" timestamp DEFAULT now() NOT NULL);
CREATE INDEX "file_artifacts_owner_idx" ON "file_artifacts"("owner_id","created_at"); CREATE INDEX "node_requests_node_idx" ON "node_protocol_requests"("node_device_id","created_at");
